471	import net.officefloor.hq.app.Audit;
472	import net.officefloor.hq.app.person.Person;
473	import net.officefloor.hq.app.person.PersonRepository;
474	import net.officefloor.hq.app.rollup.RollupService;
475	import net.officefloor.hq.app.rollup.RollupService.Snapshot;
476	import net.officefloor.hq.app.sheet.SheetService;
477	import org.springframework.http.HttpStatus;
478	import org.springframework.stereotype.Service;
479	import org.springframework.transaction.annotation.Transactional;
480	import org.springframework.web.server.ResponseStatusException;
481	
482	@Service
483	public class ClaimService {
484	
485	    private final ClaimRepository claims;
486	    private final PersonRepository people;
487	    private final RollupService rollup;
488	    private final SheetService sheets;
489	    private final Audit audit;
490	
491	    public ClaimService(ClaimRepository claims, PersonRepository people, RollupService rollup, SheetService sheets,
492	            Audit audit) {
493	        this.claims = claims;
494	        this.people = people;
495	        this.rollup = rollup;
496	        this.sheets = sheets;
497	        this.audit = audit;
498	    }
499	
500	    /** The sheet's claims, newest first. */
501	    @Transactional(readOnly = true)
502	    public List<Claim> list(String sheetId) {
503	        sheets.today(sheetId); // the sheet must exist
504	        return claims.findBySheetIdOrderByIdDesc(sheetId);
505	    }
506	
507	    /** Add a claim for a person; a claim without a date is dated the sheet's today. */
508	    @Transactional
509	    public Claim add(String user, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note) {
510	        LocalDate today = sheets.today(sheetId);
511	        Person person = requirePerson(sheetId, personId);
512	        Snapshot before = rollup.snapshot(sheetId);
513	        Claim claim = claims.saveAndFlush(
514	                new Claim(sheetId, personId, amount, date != null ? date : today, noteOf(note)));
515	        audit.recordOnCommit(entry("CLAIM_ADDED", user, person, claim));
516	        rollup.recordChanges(user, sheetId, before);
517	        return claim;
518	    }
519	
520	    @Transactional
521	    public Claim update(String user, String sheetId, Long id, BigDecimal amount, LocalDate date, String note) {
522	        LocalDate today = sheets.today(sheetId);
523	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
524	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
525	        Snapshot before = rollup.snapshot(sheetId);
526	        claim.setAmount(amount);
527	        claim.setDate(date != null ? date : today);
528	        claim.setNote(noteOf(note));
529	        claims.flush();
530	        audit.recordOnCommit(entry("CLAIM_EDITED", user, requirePerson(sheetId, claim.getPersonId()), claim));
531	        rollup.recordChanges(user, sheetId, before);
532	        return claim;
533	    }
534	
535	    /** Move a claim to another status; a change its status does not allow is refused. */
536	    @Transactional
537	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
538	        sheets.today(sheetId); // the sheet must exist
539	        // Taking the number first locks the sheet, so claims are opened one at a time; a refused
540	        // open rolls back and gives the number back.
541	        Integer number = next == ClaimStatus.OPEN ? sheets.nextClaimNumber(sheetId) : null;
542	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
543	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
544	        if (!claim.getStatus().canBecome(next)) {
545	            throw new ResponseStatusException(HttpStatus.CONFLICT,
546	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
547	        }
548	        // Four eyes: whoever opened a claim cannot also settle it.
549	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
550	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
551	        }
552	        Person person = requirePerson(sheetId, claim.getPersonId());
553	        Snapshot before = rollup.snapshot(sheetId);
554	        claim.setStatus(next);
555	        if (next == ClaimStatus.OPEN) {
556	            claim.setNumber(number);
557	            claim.setOpenedBy(user);
558	        }
559	        // A voided claim's line carries the number it had.
560	        String entry = entry(EVENTS.get(next), user, person, claim);
561	        if (next == ClaimStatus.SETTLED) {
562	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
563	            // the rate its grade has on its date; with no figure it stays live.
564	            claim.setSettledDue(figureOf(claim, person.getGrade()));
565	            entry += " due=" + (claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : "n/a");
566	        }
567	        if (next == ClaimStatus.VOID) {
568	            claim.setNumber(null);
569	        }
570	        claims.flush();
571	        audit.recordOnCommit(entry);
572	        rollup.recordChanges(user, sheetId, before);
573	        return claim;
574	    }
575	
576	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
577	            ClaimStatus.OPEN, "CLAIM_OPENED",
578	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
579	            ClaimStatus.VOID, "CLAIM_VOIDED");
580	
581	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
582	     * else what is due at its grade's rate; none when that is n/a. */
583	    public BigDecimal figureOf(Claim claim, String grade) {
584	        return rollup.figureOf(claim, grade);
585	    }
586	
587	    private Person requirePerson(String sheetId, Long personId) {
588	        return people.findByIdAndSheetId(personId, sheetId)
589	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
590	    }
591	
592	    /** The amount is written as the screen shows it, with two decimals; the date as yyyy-mm-dd; a
593	     * claim with a number ends with it. */
594	    private static String entry(String event, String user, Person person, Claim claim) {
595	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
596	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
597	                + (claim.getNumber() != null ? " number=" + claim.getNumber() : "");
598	    }
599	
600	    private static String noteOf(String note) {
601	        return note == null ? "" : note.trim();
602	    }
603	}
604	package net.officefloor.hq.app.claim;
605	
606	/** A claim's status. Only OPEN and SETTLED claims count toward what is claimed and due. */
607	public enum ClaimStatus {
608	    DRAFT, OPEN, SETTLED, VOID;
609	
610	    /** Whether a claim in this status may move to the given status. */
611	    public boolean canBecome(ClaimStatus next) {
612	        return switch (next) {
613	            case OPEN -> this == DRAFT;
614	            case SETTLED -> this == OPEN;
615	            case VOID -> this == DRAFT || this == OPEN;
616	            case DRAFT -> false;
617	        };
618	    }
619	}
620	package net.officefloor.hq.app.rollup;
621	
622	import java.math.BigDecimal;
623	import java.math.RoundingMode;
624	import java.time.LocalDate;
625	import java.util.ArrayList;
626	import java.util.LinkedHashMap;
627	import java.util.List;
628	import java.util.Map;
629	import java.util.Objects;
630	import net.officefloor.hq.app.Audit;
631	import net.officefloor.hq.app.claim.Claim;
632	import net.officefloor.hq.app.claim.ClaimRepository;
633	import net.officefloor.hq.app.claim.ClaimStatus;
634	import net.officefloor.hq.app.person.Person;
635	import net.officefloor.hq.app.person.PersonRepository;
636	import net.officefloor.hq.app.rate.Rate;
637	import net.officefloor.hq.app.rate.RateRepository;
638	import net.officefloor.hq.app.sheet.SheetRepository;
639	import org.springframework.stereotype.Service;
640	
641	/**
642	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
643	 * claimed-total and due-total. A change takes them before it alters anything and hands them back after, and
644	 * every figure it moved is written to the audit after the change's own lines. Called within the change's
645	 * transaction.
646	 */
647	@Service
648	public class RollupService {
649	
650	    /** Shown in place of a due-total whose grade has no rate. */
651	    private static final String NO_RATE = "n/a";
652	
653	    /** A person's figures, as the screen shows them. */
654	    public record Figures(String name, String claimed, String dueTotal) {}
655	
656	    /** The sheet's figures at one moment: each person's by id, in the order they were added, and the totals. */
657	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}
658	
659	    private final PersonRepository people;
660	    private final ClaimRepository claims;
661	    private final RateRepository rates;
662	    private final SheetRepository sheets;
663	    private final Audit audit;
664	
665	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
666	            SheetRepository sheets, Audit audit) {
667	        this.people = people;
668	        this.claims = claims;
669	        this.rates = rates;
670	        this.sheets = sheets;
671	        this.audit = audit;
672	    }
673	
674	    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
675	    public Snapshot snapshot(String sheetId) {
676	        LocalDate today = sheets.findById(sheetId).map(s -> s.getToday()).orElse(null);
677	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
678	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
679	            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
680	        }
681	        Map<Long, Figures> figures = new LinkedHashMap<>();
682	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
683	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
684	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
685	            List<Rate> gradeRates = rates.findBySheetIdAndGrade(sheetId, person.getGrade());
686	            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
687	                    .filter(RollupService::counts).toList();
688	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
689	            BigDecimal due = BigDecimal.ZERO.setScale(2);
690	            boolean frozen = false;
691	            for (Claim claim : counted) {
692	                claimed = claimed.add(claim.getAmount().setScale(2));
693	                frozen |= claim.getSettledDue() != null || claim.isStated();
694	                BigDecimal figure = figureOf(claim, gradeRates);
695	                if (figure != null) {
696	                    due = due.add(figure.setScale(2));
697	                }
698	            }
699	            // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
700	            boolean rated = today != null && Rate.inForce(gradeRates, today).isPresent();
701	            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
702	            claimedTotal = claimedTotal.add(claimed);
703	            if (rated || frozen) {
704	                dueTotal = dueTotal.add(due);
705	            }
706	            figures.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), personDue));
707	        }
708	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
709	    }
710	
711	    /**
712	     * Write to the audit, once the change commits, one ROLLUP line for each person whose figures moved since
713	     * {@code before} (a person new since then counts as moved), in the order they were added, then a TOTALS
714	     * line when the sheet's totals moved.
715	     */
716	    public void recordChanges(String user, String sheetId, Snapshot before) {
717	        claims.flush();
718	        Snapshot after = snapshot(sheetId);
719	        String prefix = " sheet=" + sheetId + " by=" + user;
720	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
721	            Figures now = e.getValue();
722	            Figures was = before.people().get(e.getKey());
723	            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())) {
724	                continue;
725	            }
726	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
727	                    + " due-total=" + now.dueTotal());
728	        }
729	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
730	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
731	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
732	                    + " due-total=" + after.dueTotal());
733	        }
734	    }
735	
736	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
737	     * else what is due at its grade's rate; none when that is n/a. */
738	    public BigDecimal figureOf(Claim claim, String grade) {
739	        return figureOf(claim, rates.findBySheetIdAndGrade(claim.getSheetId(), grade));
740	    }
741	
742	    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates) {
743	        if (claim.getSettledDue() != null) {
744	            return claim.getSettledDue();
745	        }
746	        return claim.isStated() ? claim.getStatedDue() : dueOf(claim, gradeRates);
747	    }
748	
749	    /** What is due on a claim at the rate its grade has in force on the claim's date, rounded half to even to two
750	     * decimals; none when no rate of the grade applies then. */
751	    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates) {
752	        BigDecimal amount = claim.getAmount();
753	        return Rate.inForce(gradeRates, claim.getDate())
754	                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
755	                .orElse(null);
756	    }
757	
758	    /** Only OPEN and SETTLED claims count toward what is claimed and due. */
759	    private static boolean counts(Claim claim) {
760	        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
761	    }
762	}
