764	
765	import java.io.IOException;
766	import java.io.UncheckedIOException;
767	import java.nio.charset.StandardCharsets;
768	import java.nio.file.Files;
769	import java.nio.file.Path;
770	import java.nio.file.StandardOpenOption;
771	import org.springframework.beans.factory.annotation.Value;
772	import org.springframework.stereotype.Service;
773	import org.springframework.transaction.support.TransactionSynchronization;
774	import org.springframework.transaction.support.TransactionSynchronizationManager;
775	
776	/**
777	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
778	 * so tests can assert side-effects by reading that file — the second test-assertion channel
779	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
780	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
781	 *
782	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
783	 * SYNC) so a test reads the record immediately.
784	 */
785	@Service
786	public class Audit {
787	
788	    private final Path file;
789	
790	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
791	        this.file = Path.of(path);
792	    }
793	
794	    /** Append one audit record. Tests assert the exact line(s) in the file. */
795	    public synchronized void record(String entry) {
796	        try {
797	            Path parent = file.toAbsolutePath().getParent();
798	            if (parent != null) {
799	                Files.createDirectories(parent);
800	            }
801	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
802	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
803	        } catch (IOException e) {
804	            throw new UncheckedIOException(e);
805	        }
806	    }
807	
808	    /**
809	     * Append one audit record once the current transaction commits, so a change that is refused or
810	     * rolled back writes nothing. Outside a transaction the record is appended at once.
811	     */
812	    public void recordOnCommit(String entry) {
813	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
814	            record(entry);
815	            return;
816	        }
